/// Helper: create a fresh linear memory + guest view.
fn fresh_guest(layout: &MemoryLayout) -> (Vec<u8>, Guest<'static>) {
    let mut mem = vec![0u8; layout.total_bytes()];
    init_memory(&mut mem, layout);
    // Leak so the borrow is 'static; the underlying buffer lives for the test.
    let mem = Box::leak(mem.into_boxed_slice());
    let guest = Guest::new(mem, layout);
    (unsafe { std::slice::from_raw_parts_mut(mem.as_mut_ptr(), mem.len()).to_vec() }, guest)
}

/// Build a buffer + guest, then hand the buffer back out for host creation.
struct Memory {
    mem: Vec<u8>,
    layout: MemoryLayout,
}

