//! Frame semantics over the shared ring: coalescing of multiple produced
//! frames, `pending()` accounting, `frame_count` monotonicity, the fresh-host
//! edge case, and value-type coverage for `set_property`.

use pathland_opcode::{
    component_type, init_memory, property_id, value_type, Guest, Host, MemoryLayout, Opcode,
    APPEND,
};

struct Memory {
    mem: Vec<u8>,
    layout: MemoryLayout,
}

impl Memory {
    fn new(layout: MemoryLayout) -> Self {
        let mut mem = vec![0u8; layout.total_bytes()];
        init_memory(&mut mem, &layout);
        Self { mem, layout }
    }

    fn guest(&mut self) -> Guest<'_> {
        Guest::new(&mut self.mem, &self.layout)
    }

    fn host(&mut self) -> Host<'_> {
        Host::new(&mut self.mem, &self.layout)
    }
}

#[test]
fn multiple_frames_coalesce_into_one() {
    let mut m = Memory::new(MemoryLayout::default());

    // Frame 1: two opcodes.
    {
        let mut g = m.guest();
        g.begin_frame();
        g.create_node(1, component_type::VSTACK).unwrap();
        g.create_node(2, component_type::HSTACK).unwrap();
        g.end_frame();
        assert_eq!(g.frame_count(), 1);
    }
    // Frame 2: one opcode.
    {
        let mut g = m.guest();
        g.begin_frame();
        g.create_node(3, component_type::TEXT).unwrap();
        g.end_frame();
        assert_eq!(g.frame_count(), 2);
    }

    // A single drain returns one coalesced frame with all three opcodes, in order.
    let mut h = m.host();
    let frames = h.frames();
    assert_eq!(frames.len(), 1);
    let ops: Vec<Opcode> = frames[0].opcodes().collect();
    assert_eq!(ops.len(), 3);
    assert_eq!(ops[0].a(), 1);
    assert_eq!(ops[1].a(), 2);
    assert_eq!(ops[2].a(), 3);

    // Subsequent drains are empty.
    assert!(h.frames().is_empty());
}

#[test]
fn fresh_host_after_another_host_drained_returns_empty() {
    let mut m = Memory::new(MemoryLayout::default());

    {
        let mut g = m.guest();
        g.begin_frame();
        g.create_node(1, component_type::VSTACK).unwrap();
        g.end_frame();
    }

    // Host 1 drains the frame, advancing readCursor.
    {
        let mut h1 = m.host();
        assert_eq!(h1.frames().len(), 1);
    }

    // A fresh Host 2 starts with consumed=0 but the cursors already agree
    // (readCursor == writeCursor), so it must NOT spin out empty frames.
    let mut h2 = m.host();
    assert!(h2.frames().is_empty());
}

#[test]
fn pending_counts_opcodes_since_begin_frame() {
    let mut m = Memory::new(MemoryLayout::default());

    {
        let mut g = m.guest();
        g.begin_frame();
        assert_eq!(g.pending(), 0);
        g.create_node(1, component_type::VSTACK).unwrap();
        g.create_node(2, component_type::TEXT).unwrap();
        assert_eq!(g.pending(), 2);
        g.end_frame();
    }

    // A new begin_frame resets the accounting window.
    {
        let mut g = m.guest();
        g.begin_frame();
        assert_eq!(g.pending(), 0);
        g.create_node(3, component_type::HSTACK).unwrap();
        assert_eq!(g.pending(), 1);
        g.end_frame();
    }
}

#[test]
fn frame_count_is_monotonic() {
    let mut m = Memory::new(MemoryLayout::default());
    let mut g = m.guest();
    assert_eq!(g.frame_count(), 0);
    for expected in 1..=5 {
        g.begin_frame();
        g.create_node(expected, component_type::VSTACK).unwrap();
        g.end_frame();
        assert_eq!(g.frame_count(), expected);
    }
}

#[test]
fn all_value_types_encode_into_b_field() {
    let mut m = Memory::new(MemoryLayout::default());
    let mut g = m.guest();
    g.begin_frame();

    // (value_type, property_id) -> expected B
    let cases: &[(u8, u16, u32)] = &[
        (value_type::U8, property_id::LINE_LIMIT, 1),
        (value_type::U32, property_id::Z_INDEX, 42),
        (value_type::I32, property_id::PADDING_TOP, 7),
        (value_type::F32, property_id::SPACING, 4.0f32.to_bits()),
        (value_type::STRING, property_id::FONT_FAMILY, 0),
        (value_type::ENUM, property_id::ALIGNMENT, 1),
        (value_type::COLOR, property_id::COLOR, 0xFF00_00FF),
        (value_type::DESIGN_TOKEN, property_id::PADDING, 0),
    ];

    for (vt, pid, value) in cases {
        g.set_property(1, *pid, *vt, *value).unwrap();
    }
    g.end_frame();

    let mut h = m.host();
    let ops: Vec<Opcode> = h.frames()[0].opcodes().collect();
    assert_eq!(ops.len(), cases.len());
    for (op, (vt, pid, _)) in ops.iter().zip(cases) {
        assert_eq!(op.category(), pathland_opcode::category::STYLE);
        assert_eq!(op.command(), pathland_opcode::style::SET_PROPERTY);
        assert_eq!(op.b(), (*vt as u32) << 16 | *pid as u32);
    }
}

#[test]
fn insert_child_with_explicit_index_round_trips() {
    let mut m = Memory::new(MemoryLayout::default());

    {
        let mut g = m.guest();
        g.begin_frame();
        g.create_node(1, component_type::VSTACK).unwrap();
        g.create_node(2, component_type::TEXT).unwrap();
        g.create_node(3, component_type::TEXT).unwrap();
        g.insert_child(1, 2, APPEND).unwrap();
        g.insert_child(1, 3, 0).unwrap();
        g.end_frame();
    }

    let mut h = m.host();
    let ops: Vec<Opcode> = h.frames()[0].opcodes().collect();
    assert_eq!(ops[3].command(), pathland_opcode::tree::INSERT_CHILD);
    assert_eq!(ops[3].c(), APPEND);
    assert_eq!(ops[4].command(), pathland_opcode::tree::INSERT_CHILD);
    assert_eq!(ops[4].c(), 0);
}

//! Host → guest event-ring tests over the public API: backpressure (full ring),
//! FIFO ordering of multiple events, and drain-twice-is-empty.

use pathland_opcode::{init_memory, Event, Host, MemoryLayout, RingError};

struct Memory {
    mem: Vec<u8>,
    layout: MemoryLayout,
}

impl Memory {
    fn new(layout: MemoryLayout) -> Self {
        let mut mem = vec![0u8; layout.total_bytes()];
        init_memory(&mut mem, &layout);
        Self { mem, layout }
    }

    fn guest(&mut self) -> pathland_opcode::Guest<'_> {
        pathland_opcode::Guest::new(&mut self.mem, &self.layout)
    }

    fn host(&mut self) -> Host<'_> {
        Host::new(&mut self.mem, &self.layout)
    }
}

fn pointer_up(target: u32, x: f32, y: f32) -> Event {
    Event::PointerUp {
        target,
        x,
        y,
        secondary: false,
    }
}

#[test]
fn events_are_delivered_in_fifo_order() {
    let mut m = Memory::new(MemoryLayout::default());

    {
        let mut h = m.host();
        h.send_event(&pointer_up(1, 1.0, 2.0)).unwrap();
        h.send_event(&pointer_up(2, 3.0, 4.0)).unwrap();
        h.send_event(&pointer_up(3, 5.0, 6.0)).unwrap();
    }

    let mut g = m.guest();
    let events = g.drain_events();
    assert_eq!(
        events,
        vec![pointer_up(1, 1.0, 2.0), pointer_up(2, 3.0, 4.0), pointer_up(3, 5.0, 6.0)]
    );

    // Second drain is empty.
    assert!(g.drain_events().is_empty());
}

#[test]
fn event_ring_reports_full() {
    // Tiny ring: slot_count=2 -> usable capacity is slot_count-1 = 1 event.
    let layout = MemoryLayout {
        slot_count: 2,
        arena_bytes: 1 << 10,
    };
    let mut m = Memory::new(layout);

    let mut h = m.host();
    assert!(h.send_event(&pointer_up(1, 0.0, 0.0)).is_ok());
    assert_eq!(
        h.send_event(&pointer_up(2, 0.0, 0.0)).unwrap_err(),
        RingError::Full
    );

    // Draining frees a slot so the host can write again.
    {
        let mut g = m.guest();
        assert_eq!(g.drain_events().len(), 1);
    }
    assert!(h.send_event(&pointer_up(3, 0.0, 0.0)).is_ok());
}

#[test]
fn events_and_tree_rings_are_independent() {
    let mut m = Memory::new(MemoryLayout::default());

    // Interleave a tree frame and events; each direction must not corrupt the other.
    {
        let mut g = m.guest();
        g.begin_frame();
        g.create_node(1, pathland_opcode::component_type::VSTACK).unwrap();
        g.end_frame();
    }
    {
        let mut h = m.host();
        h.send_event(&pointer_up(9, 1.0, 2.0)).unwrap();
    }

    let mut g = m.guest();
    assert_eq!(g.drain_events(), vec![pointer_up(9, 1.0, 2.0)]);

    let mut h = m.host();
    let ops: Vec<_> = h.frames()[0].opcodes().collect();
    assert_eq!(ops.len(), 1);
    assert_eq!(ops[0].a(), 1);
}

//! `SharedHeader` is the zero-copy read surface a foreign driver uses to read
//! the ring in place, without a `Host` handle. These tests assert its accessors
//! report the same values the header block actually holds.

use pathland_opcode::{
    component_type, init_memory, SharedHeader, Guest, Host, MemoryLayout,
};

#[test]
fn shared_header_reflects_ring_activity() {
    let layout = MemoryLayout::default();
    let mut mem = vec![0u8; layout.total_bytes()];
    init_memory(&mut mem, &layout);

    {
        let mut g = Guest::new(&mut mem, &layout);
        g.begin_frame();
        g.create_node(1, component_type::VSTACK).unwrap();
        g.end_frame();
    }

    let header = SharedHeader::new(&mem);
    assert_eq!(header.frame_count(), 1);
    assert_eq!(header.slot_count(), layout.slot_count as u32);
    assert_eq!(header.ring_offset(), layout.ring_offset() as u32);
    assert_eq!(header.ring_bytes(), layout.ring_bytes() as u32);
    assert_eq!(header.arena_offset(), layout.arena_offset() as u32);
    // Guest wrote 1 opcode: writeCursor advanced, readCursor untouched.
    assert_eq!(header.write_cursor(), 1);
    assert_eq!(header.read_cursor(), 0);
    // No arena data allocated yet.
    assert_eq!(header.arena_cursor(), 0);
}

#[test]
fn shared_header_tracks_arena_and_consumer() {
    let layout = MemoryLayout::default();
    let mut mem = vec![0u8; layout.total_bytes()];
    init_memory(&mut mem, &layout);

    let arena_ref = {
        let mut g = Guest::new(&mut mem, &layout);
        g.begin_frame();
        g.create_node(1, component_type::TEXT).unwrap();
        let ref_ = g.set_text(1, "abc").unwrap();
        g.end_frame();
        ref_
    };

    {
        let mut h = Host::new(&mut mem, &layout);
        assert_eq!(h.frames().len(), 1);
    }

    let header = SharedHeader::new(&mem);
    // Arena entry for "abc": [len u32][3 bytes] = 7 bytes consumed.
    assert_eq!(header.arena_cursor(), arena_ref + 4 + 3);
    // Consumer drained the single opcode: readCursor caught up to writeCursor.
    assert_eq!(header.read_cursor(), header.write_cursor());
}

#[test]
fn shared_header_on_fresh_memory_is_zeroed() {
    let layout = MemoryLayout::default();
    let mut mem = vec![0u8; layout.total_bytes()];
    init_memory(&mut mem, &layout);

    let header = SharedHeader::new(&mem);
    assert_eq!(header.frame_count(), 0);
    assert_eq!(header.read_cursor(), 0);
    assert_eq!(header.write_cursor(), 0);
    assert_eq!(header.arena_cursor(), 0);
}

//! Arena behaviour over the public API: `Guest::alloc`/`alloc_str` write
//! self-describing entries that `Frame::arena_get`/`arena_str` read back, plus
//! the error paths (`OutOfSpace`, `InvalidOffset`, invalid UTF-8).

use pathland_opcode::{init_memory, ArenaError, Guest, Host, MemoryLayout};

struct Memory {
    mem: Vec<u8>,
    layout: MemoryLayout,
}

impl Memory {
    fn new(layout: MemoryLayout) -> Self {
        let mut mem = vec![0u8; layout.total_bytes()];
        init_memory(&mut mem, &layout);
        Self { mem, layout }
    }

    fn guest(&mut self) -> Guest<'_> {
        Guest::new(&mut self.mem, &self.layout)
    }

    fn host(&mut self) -> Host<'_> {
        Host::new(&mut self.mem, &self.layout)
    }
}

#[test]
fn alloc_and_alloc_str_round_trip() {
    let mut m = Memory::new(MemoryLayout::default());

    let (o1, o2, o3) = {
        let mut g = m.guest();
        g.begin_frame();
        let o1 = g.alloc(&[1, 2, 3, 4]).unwrap();
        let o2 = g.alloc_str("hello").unwrap();
        let o3 = g.alloc(&[]).unwrap();
        g.end_frame();
        (o1, o2, o3)
    };

    let mut h = m.host();
    let frame = &h.frames()[0];
    assert_eq!(frame.arena_get(o1).unwrap(), &[1, 2, 3, 4]);
    assert_eq!(frame.arena_str(o2).unwrap(), "hello");
    // Empty allocation: a 4-byte (length 0) entry.
    assert_eq!(frame.arena_get(o3).unwrap(), &[]);
}

#[test]
fn out_of_space_is_reported_via_guest_alloc() {
    let layout = MemoryLayout {
        slot_count: 64,
        arena_bytes: 8,
    };
    let mut m = Memory::new(layout);

    let mut g = m.guest();
    // 8 bytes of arena fits exactly one 4-byte-length + 4-byte payload.
    assert!(g.alloc(&[1, 2, 3, 4]).is_ok());
    // Next allocation of any size must fail.
    assert_eq!(g.alloc(&[5]).unwrap_err(), ArenaError::OutOfSpace);
}

#[test]
fn set_text_maps_arena_full_to_ring_full() {
    let layout = MemoryLayout {
        slot_count: 64,
        arena_bytes: 8,
    };
    let mut m = Memory::new(layout);

    let mut g = m.guest();
    g.create_node(1, pathland_opcode::component_type::TEXT).unwrap();
    // Arena only fits ~4 bytes of payload; a larger string overflows.
    let err = g.set_text(1, "this string is far too long for an 8-byte arena").unwrap_err();
    assert_eq!(err, pathland_opcode::RingError::Full);
}

#[test]
fn invalid_offset_is_reported() {
    let mut m = Memory::new(MemoryLayout::default());
    let o = {
        let mut g = m.guest();
        g.begin_frame();
        let o = g.alloc_str("hi").unwrap();
        g.end_frame();
        o
    };

    let mut h = m.host();
    let frame = &h.frames()[0];

    // Offset far past the arena.
    let bad: u32 = (m.layout.arena_bytes + 10) as u32;
    assert_eq!(frame.arena_get(bad).unwrap_err(), ArenaError::InvalidOffset);

    // Offset into the middle of a live entry is still valid ("hi").
    assert_eq!(frame.arena_str(o).unwrap(), "hi");
}

#[test]
fn invalid_utf8_in_arena_is_rejected_by_arena_str() {
    let mut m = Memory::new(MemoryLayout::default());
    let o = {
        let mut g = m.guest();
        g.begin_frame();
        // 0xFF is not valid UTF-8.
        let o = g.alloc(&[0xFF, 0xFE, 0xFD]).unwrap();
        g.end_frame();
        o
    };

    let mut h = m.host();
    let frame = &h.frames()[0];
    // Bytes are retrievable, but interpreting them as a string fails.
    assert_eq!(frame.arena_get(o).unwrap(), &[0xFF, 0xFE, 0xFD]);
    assert_eq!(frame.arena_str(o).unwrap_err(), ArenaError::InvalidOffset);
}

//! Deterministic randomized round-trip test. A small LCG PRNG (no external
//! dependencies) generates a large sequence of opcodes across multiple frames,
//! written by a `Guest` and read back by a `Host`. It asserts exact integrity:
//! opcode count, field-for-field equality, and arena string contents. Fixed
//! conformance vectors can miss off-by-one / wraparound bugs; a long randomized
//! run makes the ring wrap many times.

use pathland_opcode::{
    component_type, init_memory, property_id, value_type, Guest, Host, MemoryLayout, Opcode,
    APPEND,
};

/// Simple deterministic LCG (Numerical Recipes). Returns a value in [0, 2^32).
struct Lcg(u64);

impl Lcg {
    fn next_u32(&mut self) -> u32 {
        self.0 = self.0.wrapping_mul(1664525).wrapping_add(1013904223);
        (self.0 >> 32) as u32
    }

    fn below(&mut self, n: u32) -> u32 {
        self.next_u32() % n
    }
}

#[test]
fn random_sequences_round_trip_exactly() {
    // Small ring so the write cursor wraps many times over the run.
    let layout = MemoryLayout {
        slot_count: 16,
        arena_bytes: 1 << 16,
    };
    let mut mem = vec![0u8; layout.total_bytes()];
    init_memory(&mut mem, &layout);

    // The full opcode stream we expect to read back.
    let mut expected: Vec<Opcode> = Vec::new();
    let mut arena_strings: Vec<(u32, String)> = Vec::new();

    let mut rng = Lcg(0xC0FF_EE00);
    let frames = 200usize;
    let max_ops = 60usize;

    {
        let mut g = Guest::new(&mut mem, &layout);
        let mut node_counter = 0u32;
        for _ in 0..frames {
            g.begin_frame();
            let n = (rng.below(max_ops as u32) as usize) + 1;
            for _ in 0..n {
                // 0..5 select an opcode kind; create_node + set_property dominate.
                match rng.below(6) {
                    0 => {
                        node_counter += 1;
                        let comp = match rng.below(4) {
                            0 => component_type::VSTACK,
                            1 => component_type::HSTACK,
                            _ => component_type::TEXT,
                        };
                        g.create_node(node_counter, comp).unwrap();
                        expected.push(Opcode::new(
                            pathland_opcode::category::TREE,
                            pathland_opcode::tree::CREATE_NODE,
                            0,
                            node_counter,
                            comp as u32,
                            0,
                        ));
                    }
                    1 => {
                        let id = node_counter.max(1);
                        let value = rng.next_u32();
                        g.set_property(id, property_id::COLOR, value_type::U32, value).unwrap();
                        expected.push(Opcode::new(
                            pathland_opcode::category::STYLE,
                            pathland_opcode::style::SET_PROPERTY,
                            0,
                            id,
                            (value_type::U32 as u32) << 16 | property_id::COLOR as u32,
                            value,
                        ));
                    }
                    2 => {
                        let id = node_counter.max(1);
                        let parent = node_counter.saturating_sub(1);
                        g.insert_child(parent, id, APPEND).unwrap();
                        expected.push(Opcode::new(
                            pathland_opcode::category::TREE,
                            pathland_opcode::tree::INSERT_CHILD,
                            0,
                            parent,
                            id,
                            APPEND,
                        ));
                    }
                    3 => {
                        // Variable-length text via the arena.
                        let id = node_counter.max(1);
                        let len = (rng.below(12) as usize) + 1;
                        let text: String = (0..len)
                            .map(|i| char::from(b'a' + ((i as u32 + rng.next_u32()) % 26) as u8))
                            .collect();
                        let arena_ref = g.set_text(id, &text).unwrap();
                        arena_strings.push((arena_ref, text));
                        expected.push(Opcode::new(
                            pathland_opcode::category::STYLE,
                            pathland_opcode::style::SET_TEXT,
                            0,
                            id,
                            arena_ref,
                            0,
                        ));
                    }
                    4 => {
                        if node_counter > 0 {
                            g.delete_node(node_counter).unwrap();
                            expected.push(Opcode::new(
                                pathland_opcode::category::TREE,
                                pathland_opcode::tree::DELETE_NODE,
                                0,
                                node_counter,
                                0,
                                0,
                            ));
                        }
                    }
                    _ => {
                        // reset is allowed mid-stream; META crosses the ring too.
                        g.reset().unwrap();
                        expected.push(Opcode::new(
                            pathland_opcode::category::META,
                            pathland_opcode::meta::RESET,
                            0,
                            0,
                            0,
                            0,
                        ));
                    }
                }
            }
            g.end_frame();
        }
    }

    // Drain everything the guest produced and compare field-for-field.
    let mut h = Host::new(&mut mem, &layout);
    let frames = h.frames();
    assert_eq!(frames.len(), 1);
    let frame = &frames[0];

    let actual: Vec<Opcode> = frame.opcodes().collect();
    assert_eq!(actual.len(), expected.len(), "opcode count mismatch");
    for (i, (a, e)) in actual.iter().zip(expected.iter()).enumerate() {
        assert_eq!(a.category(), e.category(), "category mismatch at {i}");
        assert_eq!(a.command(), e.command(), "command mismatch at {i}");
        assert_eq!(a.flags(), e.flags(), "flags mismatch at {i}");
        assert_eq!(a.a(), e.a(), "a mismatch at {i}");
        assert_eq!(a.b(), e.b(), "b mismatch at {i}");
        assert_eq!(a.c(), e.c(), "c mismatch at {i}");
    }

    // Arena strings must all be readable and match.
    for (offset, text) in &arena_strings {
        assert_eq!(frame.arena_str(*offset).unwrap(), text.as_str());
    }
}

#[test]
fn random_events_round_trip_exactly() {
    let layout = MemoryLayout::default();
    let mut mem = vec![0u8; layout.total_bytes()];
    init_memory(&mut mem, &layout);

    let mut rng = Lcg(0xDEAD_BEEF);
    let mut expected: Vec<pathland_opcode::Event> = Vec::new();

    {
        let mut h = Host::new(&mut mem, &layout);
        for _ in 0..200 {
            let target = rng.next_u32();
            let x = f32::from_bits(rng.next_u32());
            let y = f32::from_bits(rng.next_u32());
            let event = match rng.below(3) {
                0 => pathland_opcode::Event::PointerDown {
                    target,
                    x,
                    y,
                    secondary: rng.below(2) == 1,
                },
                1 => pathland_opcode::Event::PointerMove {
                    target,
                    x,
                    y,
                    hovering: rng.below(2) == 1,
                    leaving: rng.below(2) == 1,
                },
                _ => pathland_opcode::Event::PointerUp {
                    target,
                    x,
                    y,
                    secondary: rng.below(2) == 1,
                },
            };
